// One Telegram message per chunk. The HTTP node below then runs once per
// item, so a 20-job digest is delivered in full instead of being truncated.
const chunks = $('Build digest').first().json.telegram_chunks || [];
if (!chunks.length) return [{ json: { text: '', part: 0, parts: 0 } }];
return chunks.map((text, i) => ({ json: { text, part: i + 1, parts: chunks.length } }));

// Renders the same bucketed content twice: rich HTML for the record, plain
// text for Telegram. Jobs arrive already ordered and labelled by "Top matches".
const jobs = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined);
const esc = (s) =>
  String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const color = (s) => (s >= 85 ? '#0a7d32' : s >= 70 ? '#8a6d00' : '#666');
const ORDER = ['Europe', 'United States', 'Remote / Global'];
const bucketOf = (j) => (ORDER.includes(j.bucket) ? j.bucket : 'Remote / Global');

// Keep the numbering continuous across sections so 1..n still reads as a list.
let n = 0;
const numbered = jobs.map((j) => ({ ...j, section: bucketOf(j), n: ++n }));

const groups = ORDER.map((name) => ({
  name,
  items: numbered.filter((j) => j.section === name),
})).filter((g) => g.items.length);

const rowHtml = (j) =>
  '<tr>' +
  '<td style="padding:9px 8px;color:#888;vertical-align:top">' + j.n + '</td>' +
  '<td style="padding:9px 8px"><a href="' + esc(j.url) + '" style="color:#111;font-weight:600;text-decoration:none">' + esc(j.title) + '</a>' +
  '<div style="color:#666;font-size:13px">' + esc(j.company) + ' &middot; ' + esc(j.location || '-') + ' &middot; ' + esc(j.source) + '</div></td>' +
  '<td style="padding:9px 8px;text-align:right;color:' + color(j.score) + ';font-weight:700;vertical-align:top">' + esc(j.score) + '</td>' +
  '</tr>';

const rows = groups
  .map(
    (g) =>
      '<tr><td colspan="3" style="padding:14px 8px 4px;border-bottom:1px solid #e3e6ea">' +
      '<span style="font-size:12px;letter-spacing:1px;text-transform:uppercase;color:#888;font-weight:700">' +
      esc(g.name) + '</span>' +
      '<span style="color:#aaa;font-size:12px"> &middot; ' + g.items.length + '</span>' +
      '</td></tr>' +
      g.items.map(rowHtml).join('')
  )
  .join('');

const tally = groups.map((g) => g.items.length + ' ' + g.name).join(' &middot; ');

const html =
  '<div style="font-family:-apple-system,Segoe UI,sans-serif;max-width:640px">' +
  '<h2 style="margin:0 0 4px">JobPilot &middot; ' + new Date().toISOString().slice(0, 10) + '</h2>' +
  '<p style="color:#666;margin:0 0 6px">' + jobs.length + ' new roles scored 55+.</p>' +
  (groups.length ? '<p style="color:#999;font-size:13px;margin:0 0 10px">' + tally + '</p>' : '') +
  (groups.length ? '<table style="border-collapse:collapse;width:100%">' + rows + '</table>' : '<p>No new matches today.</p>') +
  '</div>';

// Telegram hard-caps a single message at 4096 characters. A 20-job digest no
// longer fits, so it is split into consecutive messages on job boundaries -
// never mid-link - and the bucket label is repeated when a group spills over.
// An empty digest still produces one message so the run stays explainable.
const CHUNK_LIMIT = 3800;

const digestTitle =
  'JobPilot - ' + jobs.length + ' new match(es)' +
  (groups.length ? '\n' + groups.map((g) => g.items.length + ' ' + g.name).join(' | ') : '');

const chunks = [];
let buf = '';
const flush = () => { if (buf) { chunks.push(buf); buf = ''; } };
const fits = (t) => !buf || buf.length + 2 + t.length <= CHUNK_LIMIT;
const add = (t) => { buf = buf ? buf + '\n\n' + t : t; };

if (groups.length) {
  add(digestTitle);
  for (const g of groups) {
    const sec = '--- ' + g.name.toUpperCase() + ' ---';
    if (!fits(sec)) flush();
    add(sec);
    for (const j of g.items) {
      const body = j.n + '. [' + j.score + '] ' + j.title + ' - ' + j.company + '\n' + (j.url || '');
      if (fits(body)) {
        add(body);
      } else {
        flush();
        const next = sec + '\n\n' + body;
        buf = next.length <= CHUNK_LIMIT ? next : body.slice(0, CHUNK_LIMIT);
      }
    }
  }
  flush();
} else {
  chunks.push('Nothing above the bar today. The pipeline is still running.');
}

const q = (v) => "'" + String(v).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
const delivered = $env.TELEGRAM_CHAT_ID ? 'telegram' : 'stored-only';

return [
  {
    json: {
      count: jobs.length,
      sections: groups.map((g) => ({ name: g.name, count: g.items.length })),
      html,
      telegram_text: chunks.join('\n\n'),
      telegram_chunks: chunks,
      delivered_via: delivered,
      save_sql:
        'INSERT INTO digests (job_count, html, delivered_via) VALUES (' +
        jobs.length +
        ',' +
        q(html) +
        ',' +
        q(delivered) +
        ');',
    },
  },
];

const d = $('Build digest').first().json;
const telegram = $env.TELEGRAM_CHAT_ID ? 'enabled' : 'skipped (no TELEGRAM_CHAT_ID)';
return [
  {
    json: {
      matches: d.count,
      sections: (d.sections || []).map((x) => x.count + ' ' + x.name).join(', '),
      telegram,
      html_bytes: d.html.length,
      note: d.count
        ? 'Digest rendered. Open the digests table to view the HTML.'
        : 'No job scored 55+ today. Lower the threshold in "Top matches" if this repeats.',
    },
  },
];

// Only mark jobs as delivered once Telegram accepted EVERY message of this run,
// otherwise a failed (or partially failed) send would silently hide jobs from
// tomorrow's digest. No Telegram configured -> nothing is marked.
const ids = $('Top matches').all().map((i) => i.json.id).filter((v) => v !== undefined);
const configured = Boolean($env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID);
const responses = $input.all().map((i) => i.json || {});
const delivered = responses.length > 0 && responses.every((r) => r.ok === true);

const shouldMark = configured && delivered && ids.length > 0;

return [
  {
    json: {
      sql: shouldMark
        ? 'UPDATE jobs SET digested_at = now() WHERE id IN (' + ids.join(',') + ')'
        : 'SELECT 1 AS skipped',
      marked: shouldMark ? ids.length : 0,
      parts_sent: configured ? responses.length : 0,
      reason: !configured
        ? 'telegram not configured'
        : !delivered
          ? 'send failed - jobs kept for next run'
          : 'delivered',
    },
  },
];
